hab-dome.source:
const R=params.radius, N=24, y0=1.2, H=R*0.7;
const glass=params.glass;
const doors=[params.doorA,params.doorB,params.doorC].filter(d=>d<900);
const frameM={preset:'metal',color:params.frameColor,roughness:0.35,metalness:0.85};
const glassM={preset:'glass',color:'#9fd0dc',opacity:0.28,roughness:0.05};
const panelA={preset:'metal',color:params.panelColor,roughness:0.55,metalness:0.35};
const panelB={preset:'metal',color:params.accentColor,roughness:0.5,metalness:0.4};
const floorM={preset:'concrete',color:'#6f625a',roughness:0.85};
const wallM={preset:'concrete',color:'#d3cdc0',roughness:0.7};
const hazM={preset:'plastic',color:'#d9a400',roughness:0.6};
function isDoor(a){return doors.some(d=>{let df=((a-d)%360+360)%360; if(df>180)df=360-df; return df<8;});}
api.add(api.cylinder(R+0.35,R+0.5,0.12,48).translate(0,0.06,0),floorM);
api.add(api.cylinder(R-0.2,R-0.2,0.02,48).translate(0,0.13,0),{preset:'metal',color:'#8d9298',roughness:0.5,metalness:0.6});
api.add(api.torus(R*0.55,0.03).rotate(90,0,0).translate(0,0.15,0),hazM);
api.add(api.torus(R-0.3,0.04).rotate(90,0,0).translate(0,0.15,0),frameM);
api.collider({kind:'cylinder',halfHeight:0.06,radius:R+0.4,offset:[0,0.06,0]});
const chord=2*R*Math.sin(Math.PI/N)+0.02;
for(let j=0;j<N;j++){
  const a=j*360/N; if(isDoor(a)) continue;
  api.add(api.box(0.34,1.1,chord).translate(R-0.17,0.12+0.55,0).rotate(0,-a,0),wallM);
  const ar=a*Math.PI/180, rr=R-0.15;
  api.collider({kind:'box',halfExtents:[0.2,1.55,chord/2],offset:[Math.cos(ar)*rr,1.6,Math.sin(ar)*rr],rotation:[0,-a,0]});
}
const phis=[0,20,40,60,76];
const pts=phis.map(p=>{const r=p*Math.PI/180;return [R*Math.cos(r),y0+H*Math.sin(r)];});
for(let k=0;k<4;k++){
  const p0=pts[k],p1=pts[k+1];
  const dx=p1[0]-p0[0],dy=p1[1]-p0[1];
  const L=Math.hypot(dx,dy)*1.03, beta=Math.atan2(dy,dx)*180/Math.PI;
  const mx=(p0[0]+p1[0])/2,my=(p0[1]+p1[1])/2;
  const w=2*mx*Math.tan(Math.PI/N)+0.02;
  for(let j=0;j<N;j++){
    const a=j*360/N; if(k===0&&isDoor(a)) continue;
    let mat=glassM;
    if(!glass){ mat=(k===1)?glassM:((j%2===0)?panelA:panelB); if(k===1&&j%2===1) mat=panelA; }
    api.add(api.box(L,0.05,w).rotate(0,0,beta).translate(mx,my,0).rotate(0,-a,0),mat);
  }
}
const rc=pts[4][0];
api.add(api.cylinder(rc,rc,0.1,24).translate(0,pts[4][1],0),frameM);
api.add(api.cylinder(0.12,0.2,0.5,10).translate(0,pts[4][1]+0.3,0),frameM);
api.add(api.sphere(0.16,1).translate(0,pts[4][1]+0.65,0),{preset:'emissive',color:'#ff4a3a',emissive:'#ff4a3a',emissiveIntensity:2});
for(let j=0;j<N;j++){
  const a=(j+0.5)*360/N;
  const path=[[R,0.12,0],[R,y0,0]].concat(pts.map(p=>[p[0],p[1],0]));
  api.add(api.tube(path,0.065,5).rotate(0,-a,0),frameM);
}
for(let k=1;k<=4;k++){
  const path=[];
  for(let i=0;i<=48;i++){const t=i*Math.PI*2/48;path.push([Math.cos(t)*pts[k][0],pts[k][1],Math.sin(t)*pts[k][0]]);}
  api.add(api.tube(path,0.06,5),frameM);
}
doors.forEach(d=>{
  api.add(api.box(0.4,0.35,2.9).translate(R,3.2,0).rotate(0,-d,0),frameM);
  api.add(api.box(0.8,0.02,2.2).translate(R,0.14,0).rotate(0,-d,0),hazM);
  api.add(api.box(0.12,0.1,2.3).translate(R+0.08,3.0,0).rotate(0,-d,0),{preset:'emissive',color:'#ffb040',emissive:'#ffb040',emissiveIntensity:1.2});
});
return api.build();

glass-corridor.source:
const L=params.length, hw=params.width/2, wt=0.14, yc=1.12, b=1.9, a=hw+wt/2;
const frameM={preset:'metal',color:'#c9ccd0',roughness:0.35,metalness:0.85};
const glassM={preset:'glass',color:'#9fd0dc',opacity:0.28,roughness:0.05};
const wallM={preset:'concrete',color:'#d3cdc0',roughness:0.7};
const floorM={preset:'concrete',color:'#6f625a',roughness:0.85};
api.add(api.box(L,0.12,hw*2+wt*2+0.3).translate(0,0.06,0),floorM);
api.add(api.box(L-0.1,0.02,hw*2).translate(0,0.13,0),{preset:'metal',color:'#80868c',roughness:0.5,metalness:0.7});
api.add(api.box(L-0.4,0.025,0.1).translate(0,0.145,0),{preset:'plastic',color:'#d9a400',roughness:0.6});
[-1,1].forEach(s=>{
  api.add(api.box(L,1.0,wt).translate(0,0.62,s*a),wallM);
  api.add(api.box(L,0.06,wt+0.08).translate(0,1.15,s*a),frameM);
  api.add(api.box(L-0.6,0.04,0.05).translate(0,1.0,s*(a-wt/2-0.03)),{preset:'emissive',color:'#ffe2b0',emissive:'#ffe2b0',emissiveIntensity:0.8});
  api.collider({kind:'box',halfExtents:[L/2,1.5,wt/2+0.03],offset:[0,1.6,s*a]});
});
api.collider({kind:'box',halfExtents:[L/2,0.06,hw+wt+0.1],offset:[0,0.06,0]});
const arc=[];
for(let i=0;i<=5;i++){const t=i*Math.PI/5;arc.push([Math.cos(t)*a,yc+Math.sin(t)*b]);}
for(let i=0;i<5;i++){
  const p0=arc[i],p1=arc[i+1];
  const dz=p1[0]-p0[0],dy=p1[1]-p0[1];
  const seg=Math.hypot(dz,dy)*1.04, g=-Math.atan2(dy,dz)*180/Math.PI;
  api.add(api.box(L,0.04,seg).rotate(g,0,0).translate(0,(p0[1]+p1[1])/2,(p0[0]+p1[0])/2),glassM);
}
const n=Math.max(2,Math.round(L/2)+1);
for(let i=0;i<n;i++){
  const x=-L/2+i*L/(n-1);
  const path=[[x,0.12,-a],[x,yc,-a]].concat(arc.map(p=>[x,p[1],p[0]])).concat([[x,0.12,a]]);
  api.add(api.tube(path,0.05,5),frameM);
}
api.add(api.box(L,0.08,0.12).translate(0,yc+b+0.03,0),frameM);
return api.build();

solar-array.source:
const cols=params.cols, rows=params.rows, tilt=params.tilt;
const pw=2.0, pl=1.6, gap=0.08, spacing=4.2;
const W=cols*(pw+gap), D=rows*spacing;
const cell={preset:'glass',color:'#16295a',roughness:0.15,metalness:0.7,opacity:1};
const frame={preset:'metal',color:'#c4c8cc',roughness:0.4,metalness:0.85};
const grid={preset:'metal',color:'#7f93c4',roughness:0.3,metalness:0.8};
api.add(api.box(W+3,0.12,D+2).translate(0,0.06,0),{preset:'concrete',color:'#8a7f75',roughness:0.9});
api.collider({kind:'box',halfExtents:[(W+3)/2,0.06,(D+2)/2],offset:[0,0.06,0]});
for(let r=0;r<rows;r++){
  const z=-D/2+spacing/2+r*spacing;
  for(let c=0;c<cols;c++){
    const x=-W/2+(pw+gap)/2+c*(pw+gap);
    api.add(api.box(pw+0.06,0.05,pl+0.06).rotate(tilt,0,0).translate(x,1.35,z),frame);
    api.add(api.box(pw-0.04,0.06,pl-0.04).rotate(tilt,0,0).translate(x,1.37,z),cell);
    api.add(api.box(pw-0.04,0.07,0.03).rotate(tilt,0,0).translate(x,1.38,z),grid);
    api.add(api.box(0.03,0.07,pl-0.04).rotate(tilt,0,0).translate(x,1.38,z),grid);
  }
  api.add(api.box(W,0.1,0.12).translate(0,1.0,z),frame);
  for(let c=0;c<=cols;c+=2){
    const x=-W/2+c*(pw+gap);
    api.add(api.cylinder(0.06,0.07,1.45,8).translate(x,0.8,z-0.4),frame);
    api.add(api.cylinder(0.06,0.07,0.7,8).translate(x,0.45,z+0.5),frame);
  }
  api.collider({kind:'box',halfExtents:[W/2,0.85,0.8],offset:[0,1.0,z]});
}
api.add(api.box(1.0,1.6,0.6).translate(-W/2-1.0,0.92,-D/2+0.8),{preset:'metal',color:'#d8d2c4',roughness:0.5,metalness:0.4});
api.add(api.box(0.6,0.3,0.03).translate(-W/2-1.0,1.3,-D/2+1.12),{preset:'emissive',color:'#6aff9a',emissive:'#6aff9a',emissiveIntensity:0.6});
return api.build();

