mars-crater.source:
const Rc=params.radius, S=Rc*3.8, n=110, rim=params.rim;
const sm=t=>t*t*(3-2*t);
const hf=(x,z)=>{
  const r=Math.hypot(x,z)/Rc;
  let h;
  const nz=api.fbm2(x*0.12,z*0.12,3);
  if(r<0.72) h=0.0+Math.max(0,nz)*0.15;
  else if(r<1.0) h=rim*sm((r-0.72)/0.28);
  else if(r<1.9) h=rim*(1-sm((r-1.0)/0.9));
  else h=0;
  if(h>0.3) h*=1+nz*0.35;
  return Math.max(0,h);
};
const m=api.heightfield(n,n,S,S,hf);
m.vertexColor((x,y,z)=>{const t=Math.min(1,y/rim);return api.mix(Math.hypot(x,z)<Rc*0.75?'#7a4631':'#a65a3b','#c4764c',t*0.8);});
api.add(m,{preset:'dirt',roughness:0.95});
api.autoColliders('trimesh');
return api.build();

