comms-mast.source:
const h=params.height;
const steel={preset:'metal',color:'#d9d6cf',roughness:0.4,metalness:0.8};
const dark={preset:'metal',color:'#4a4f55',roughness:0.5,metalness:0.7};
const base=2.2, top=0.5;
const legs=[0,1,2].map(i=>{const a=i*120*Math.PI/180;return [Math.cos(a),Math.sin(a)];});
legs.forEach(l=>api.add(api.tube([[l[0]*base,0,l[1]*base],[l[0]*top,h,l[1]*top]],0.1,6),steel));
const levels=10;
for(let k=0;k<levels;k++){
  const y0=k*h/levels,y1=(k+1)*h/levels;
  const r0=base+(top-base)*k/levels, r1=base+(top-base)*(k+1)/levels;
  for(let i=0;i<3;i++){
    const a=legs[i],b=legs[(i+1)%3];
    api.add(api.tube([[a[0]*r0,y0,a[1]*r0],[b[0]*r1,y1,b[1]*r1]],0.04,4),steel);
    api.add(api.tube([[b[0]*r0,y0,b[1]*r0],[a[0]*r1,y1,a[1]*r1]],0.04,4),steel);
    api.add(api.tube([[a[0]*r1,y1,a[1]*r1],[b[0]*r1,y1,b[1]*r1]],0.05,4),steel);
  }
}
api.add(api.cylinder(2.8,3.0,0.5,12).translate(0,0.25,0),{preset:'concrete',color:'#8a7f75',roughness:0.9});
[0.45,0.55].forEach((f,i)=>{
  const y=h*(0.55+i*0.22), r=base+(top-base)*(y/h);
  const a=(40+i*130)*Math.PI/180;
  api.add(api.cylinder(0.02,1.1,0.5,18).rotate(0,0,-90).translate(Math.cos(a)*(r+0.9),y,Math.sin(a)*(r+0.9)).rotate(0,0,0),steel);
});
