kepler-dome.source:
const R = params.radius;
const D2R = Math.PI / 180;
const FL = 0.12;
const doors = [];
['doorA','doorB','doorC'].forEach(function(k){ const a = params[k]; if (a > -900) doors.push({a: a, w: 1.9, h: 2.4}); });
if (params.bay > -900) {
  let found = false;
  doors.forEach(function(d){ let df = Math.abs(((d.a - params.bay) % 360 + 540) % 360 - 180); if (df < 1) { d.w = 4.2; d.h = 3.4; found = true; } });
  if (!found) doors.push({a: params.bay, w: 4.2, h: 3.4});
}
let maxH = 2.4;
doors.forEach(function(d){ if (d.h > maxH) maxH = d.h; });
const WH = Math.max(3.0, maxH + 0.4);
const H = Math.max(R * 0.4 + 5.3, WH + 2.0);
const cap = H - WH;
const y0 = FL + WH;

let gaps = [];
doors.forEach(function(d){
  const hd = Math.asin(Math.min(0.95, (d.w / 2 + 0.06) / R)) / D2R;
  const lo = ((d.a - hd) % 360 + 360) % 360;
  const hi = lo + 2 * hd;
  if (hi > 360) { gaps.push([lo, 360]); gaps.push([0, hi - 360]); } else gaps.push([lo, hi]);
});
gaps.sort(function(a, b){ return a[0] - b[0]; });
const rem = [];
let cur = 0;
gaps.forEach(function(g){ if (g[0] > cur) rem.push([cur, g[0]]); if (g[1] > cur) cur = g[1]; });
if (cur < 360) rem.push([cur, 360]);

const wallM = [], bandM = [];
function addAt(list, mesh, ang, r, ty) {
  const th = -ang - 90;
  list.push(mesh.translate(0, ty, 0).rotate(0, th, 0).translate(r * Math.cos(ang * D2R), 0, r * Math.sin(ang * D2R)));
}
rem.forEach(function(iv){
  const n = Math.max(1, Math.ceil((iv[1] - iv[0]) / 7.5));
  const sp = (iv[1] - iv[0]) / n;
  for (let i = 0; i < n; i++) {
    const m = iv[0] + sp * (i + 0.5);
    const chord = 2 * R * Math.sin(sp * D2R / 2) + 0.04;
    const r = R * Math.cos(sp * D2R / 2);
    addAt(wallM, api.box(chord, WH, 0.18), m, r, FL + WH / 2);
    addAt(bandM, api.box(chord, 0.3, 0.26), m, r, FL + WH - 0.15);
    addAt(bandM, api.box(chord, 0.35, 0.24), m, r, FL + 0.175);
    api.collider({kind: 'box', halfExtents: [chord / 2, WH / 2, 0.09], offset: [r * Math.cos(m * D2R), FL + WH / 2, r * Math.sin(m * D2R)], rotation: [0, -m - 90, 0]});
  }
});
doors.forEach(function(d){
  const gw = d.w + 0.1;
  const lh = WH - d.h;
  if (lh > 0.05) {
    addAt(wallM, api.box(gw, lh, 0.18), d.a, R, FL + d.h + lh / 2);
  }
  addAt(bandM, api.box(gw + 0.3, 0.14, 0.3), d.a, R, FL + d.h + 0.07);
  const sa = Math.asin(Math.min(0.95, (d.w / 2 + 0.06) / R)) / D2R;
  const rr = R * Math.cos(sa * D2R);
  [-1, 1].forEach(function(s){
    addAt(bandM, api.box(0.14, d.h, 0.3), d.a + s * sa, rr, FL + d.h / 2);
  });
});
function mergeAll(list) {
  const m = list[0];
  for (let i = 1; i < list.length; i++) m.merge(list[i]);
  return m;
}
api.add(mergeAll(wallM), {preset: 'metal', color: params.panelColor, roughness: 0.55, metalness: 0.35, doubleSided: true});
api.add(mergeAll(bandM), {preset: 'metal', color: params.accentColor, roughness: 0.4, metalness: 0.6, doubleSided: true});

const prof = [];
const N = 16;
for (let i = 0; i <= N; i++) {
  const t = (i / N) * 89 * D2R;
  prof.push([R * Math.cos(t), y0 + cap * Math.sin(t)]);
}
prof.push([0.01, y0 + cap]);
const dome = api.lathe(prof, 48);
if (params.glass) {
  api.add(dome, {preset: 'glass', color: '#bcd9e4', opacity: 0.3, roughness: 0.05, metalness: 0.1, doubleSided: true});
} else {
  api.add(dome, {preset: 'metal', color: params.panelColor, roughness: 0.55, metalness: 0.35, doubleSided: true});
}
const ribs = [];
const nr = 12;
for (let k = 0; k < nr; k++) {
  const ph = (k / nr) * 2 * Math.PI;
  const path = [];
  for (let i = 0; i <= 12; i++) {
    const t = (i / 12) * 86 * D2R;
    const rr = R * Math.cos(t) + 0.03;
    path.push([rr * Math.cos(ph), y0 + cap * Math.sin(t) + 0.02, rr * Math.sin(ph)]);
  }
  ribs.push(api.tube(path, 0.07, 6));
}
[0.35, 0.65].forEach(function(f){
  const t = f * 89 * D2R;
  ribs.push(api.torus(R * Math.cos(t) + 0.03, 0.06).rotate(90, 0, 0).translate(0, y0 + cap * Math.sin(t) + 0.02, 0));
});
ribs.push(api.torus(R, 0.1).rotate(90, 0, 0).translate(0, y0, 0));
api.add(mergeAll(ribs), {preset: 'metal', color: params.accentColor, roughness: 0.4, metalness: 0.7, doubleSided: true});

api.add(api.cylinder(R + 0.25, R + 0.25, FL, 56).translate(0, FL / 2, 0), {preset: 'concrete', color: params.floorColor, roughness: 0.85, metalness: 0.05, doubleSided: true});
api.add(api.cylinder(R * 0.5, R * 0.5, 0.012, 48).translate(0, FL + 0.006, 0), {preset: 'concrete', color: params.inlayColor, roughness: 0.7, metalness: 0.15, doubleSided: true});
const fl2 = [];
fl2.push(api.torus(R * 0.51, 0.035).rotate(90, 0, 0).translate(0, FL + 0.02, 0));
fl2.push(api.torus(R + 0.05, 0.1).rotate(90, 0, 0).translate(0, FL + 0.02, 0));
api.add(mergeAll(fl2), {preset: 'metal', color: params.accentColor, roughness: 0.45, metalness: 0.6, doubleSided: true});
api.collider({kind: 'cylinder', halfHeight: FL / 2, radius: R + 0.25, offset: [0, FL / 2, 0]});
return api.build();

kepler-corridor.source:
const L = params.length, W = params.width, Hc = params.height;
const FL = 0.12, T = 0.1;
function mergeAll(list) { const m = list[0]; for (let i = 1; i < list.length; i++) m.merge(list[i]); return m; }
const mat = {preset: 'metal', color: params.color, roughness: 0.5, metalness: 0.4, doubleSided: true};
const dark = {preset: 'metal', color: '#3a4046', roughness: 0.6, metalness: 0.5, doubleSided: true};
const acc = {preset: 'plastic', color: '#d9a400', roughness: 0.5, metalness: 0.1, doubleSided: true};
const glow = {preset: 'emissive', color: '#fff0d0', emissive: '#ffd9a0', emissiveIntensity: 1.8, doubleSided: true};
const top = FL + Hc;
// floor
api.add(api.box(L, FL, W + 2 * T).translate(0, FL / 2, 0), dark);
// walls
const walls = [];
[-1, 1].forEach(function(s){ walls.push(api.box(L, Hc + 0.1, T).translate(0, FL + (Hc + 0.1) / 2 - 0.05 + 0.05, s * (W / 2 + T / 2))); });
walls.push(api.roundedBox(L, 0.14, W + 2 * T, 0.03, 2).translate(0, top + 0.07, 0));
api.add(mergeAll(walls), mat);
// ribs
const ribs = [];
const n = Math.max(1, Math.floor(L / 2.2));
for (let i = 0; i < n; i++) {
  const x = -L / 2 + (L / n) * (i + 0.5);
  [-1, 1].forEach(function(s){ ribs.push(api.box(0.14, Hc + 0.2, 0.08).translate(x, FL + (Hc + 0.2) / 2 - 0.05, s * (W / 2 + T + 0.03))); });
  ribs.push(api.box(0.14, 0.1, W + 2 * T + 0.14).translate(x, top + 0.17, 0));
}
api.add(mergeAll(ribs), dark);
// floor edge stripes and ceiling light strip
const st = [];
[-1, 1].forEach(function(s){ st.push(api.box(L - 0.1, 0.012, 0.08).translate(0, FL + 0.006, s * (W / 2 - 0.12))); });
api.add(mergeAll(st), acc);
api.add(api.box(L - 0.4, 0.04, Math.min(0.3, W * 0.2)).translate(0, top - 0.02, 0), glow);
if (params.steps) {
  api.add(api.box(0.5, 0.05, W).translate(L / 2 - 0.3, FL + 0.025, 0), acc);
}
api.collider({kind: 'box', halfExtents: [L / 2, FL / 2, (W + 2 * T) / 2], offset: [0, FL / 2, 0]});
[-1, 1].forEach(function(s){ api.collider({kind: 'box', halfExtents: [L / 2, (Hc + 0.1) / 2, T / 2], offset: [0, FL + (Hc + 0.1) / 2, s * (W / 2 + T / 2)]}); });
return api.build();

mars-regolith.source:
const E = params.extent, half = E / 2, CZ = 5;
const segs = [[70,-37,70,41],[48,0,70,0],[1.5,-77,1.5,-47],[0,46,0,53],[-41.6,24,-58,42],[-48,0,-62,-14]];
const circ = [[0,0,56],[0,68,19],[88,0,26],[6,-88,16],[-62,48,12],[-64,-18,6],[-65,-82,20],[43,55,9],[-56,-26,5],[-30,-46,4],[-90,-35,4],[-105,-5,4],[-90,25,4],[-112,50,4],[-85,70,4],[34,41,6]];
function segd(px, pz, s) { const dx = s[2]-s[0], dz = s[3]-s[1]; let t = ((px-s[0])*dx+(pz-s[1])*dz)/(dx*dx+dz*dz); t = Math.max(0, Math.min(1, t)); return Math.hypot(px-(s[0]+t*dx), pz-(s[1]+t*dz)); }
function blocked(wx, wz) {
  for (const c of circ) if (Math.hypot(wx-c[0], wz-c[1]) < c[2]) return true;
  for (const s of segs) if (segd(wx, wz, s) < 4) return true;
  return false;
}
function hgt(x, z) {
  const d = Math.hypot(x, z);
  let h = 0.018 + 0.016 * api.noise2(x * 0.08, z * 0.08) + 0.008 * api.noise2(x * 0.5, z * 0.5);
  h = Math.max(0, Math.min(0.04, h));
  if (d > 112) { const t = Math.min(1, (d - 112) / 6); h = h * (1 - t) - t; }
  return h;
}
const n = 100;
const ground = api.heightfield(n, n, E, E, hgt);
const c1 = '#7a3e27', c2 = '#b87650', c3 = '#82625a';
ground.vertexColor((x, y, z) => {
  const a = (api.noise2(x * 0.03, z * 0.03) + 1) / 2, m = (api.noise2(x * 0.18 + 40, z * 0.18) + 1) / 2;
  let c = api.mix(c1, c2, Math.max(0, Math.min(1, a)));
  return api.mix(c, c3, Math.max(0, Math.min(1, (m - 0.45) * 1.2)) * 0.5);
});
api.add(ground, { preset: 'dirt', roughness: 1, metalness: 0 });
let rocks = null;
const pal = ['#5b4740', '#6e564a', '#82675a', '#4e4340', '#8e7060'];
for (let c = 0; c < params.rocks * 2; c++) {
  const cx = (api.rng() * 2 - 1) * (half - 20), cz = (api.rng() * 2 - 1) * (half - 20);
  if (Math.hypot(cx, cz) > 106) continue;
  const cnt = 4 + Math.floor(api.rng() * 6), spread = 1.5 + api.rng() * 4;
  for (let i = 0; i < cnt; i++) {
    const x = cx + (api.rng() - 0.5) * 2 * spread, z = cz + (api.rng() - 0.5) * 2 * spread;
    if (Math.hypot(x, z) > 108 || blocked(x, z + CZ)) continue;
    const s = 0.07 + Math.pow(api.rng(), 2.5) * 0.4;
    const col = pal[Math.floor(api.rng() * pal.length)];
    const m = api.icosphereRock(s, 0.5).scale(1 + api.rng() * 0.6, 0.55, 1 + api.rng() * 0.5).rotate(0, api.rng() * 360, 0).translate(x, 0.02 + s * 0.2, z);
    m.vertexColor(() => col);
    if (rocks) rocks.merge(m); else rocks = m;
  }
}
if (rocks) api.add(rocks, { preset: 'stone', roughness: 0.95, metalness: 0 });
return api.build();

kepler-dome-lit.source:
const R = params.radius;
const floorH = 0.1, wallT = 0.3;
const doorsRaw = [params.doorA, params.doorB, params.doorC];
const doors = doorsRaw.filter(v => v >= 0);
const hasBay = params.bay >= 0;
const wallH = hasBay ? 3.8 : 2.9;
const apex = Math.max(params.apex, wallH + 0.5);
const N = 144, stepDeg = 360 / N;
const chord = 2 * R * Math.sin(Math.PI / N);
const probe = api.box(0.2, 0.2, 0.2).translate(1, 0, 0).rotate(0, 30, 0).bounds();
const sgn = probe.min[2] < 0 ? 1 : -1;
const angDiff = (a, b) => { let d = Math.abs(((a - b) % 360 + 540) % 360 - 180); return d; };
const doorInfo = (a) => {
  let best = null;
  for (const d of doors) {
    const isBay = hasBay && angDiff(d, params.bay) < 1;
    const w = isBay ? 4.4 : 2.4;
    const hh = isBay ? 3.5 : 2.6;
    const half = Math.asin(Math.min(0.99, (w / 2) / R)) * 180 / Math.PI;
    if (angDiff(a, d) - stepDeg / 2 < half - 0.01) { best = { hh: hh }; }
  }
  return best;
};
const pm = { preset: 'plastic', color: params.panelColor, roughness: 0.7, doubleSided: true };
let wall = null;
const add = (m) => { if (wall) wall.merge(m); else wall = m; };
const colliders = [];
for (let i = 0; i < N; i++) {
  const a = i * stepDeg;
  const rad = a * Math.PI / 180;
  const cx = R * Math.cos(rad), cz = R * Math.sin(rad);
  const yaw = sgn * (-a - 90);
  const di = doorInfo(a);
  const bottom = di ? di.hh : floorH;
  const h = wallH - bottom;
  if (h > 0.01) {
    add(api.box(chord + 0.03, h, wallT).rotate(0, yaw, 0).translate(cx, bottom + h / 2, cz));
  }
  if (!di) {
    colliders.push({ kind: 'box', halfExtents: [chord / 2 + 0.02, (wallH - floorH) / 2, wallT / 2], offset: [cx, floorH + (wallH - floorH) / 2, cz], rotation: [0, yaw, 0] });
  }
}
api.add(wall, pm);
const floor = api.cylinder(R, R, floorH, 72).translate(0, floorH / 2, 0);
api.add(floor, { preset: 'concrete', color: params.floorColor, roughness: 0.85, doubleSided: true });
const inlay = api.cylinder(R * 0.6, R * 0.6, 0.006, 72).translate(0, floorH + 0.003, 0);
api.add(inlay, { preset: 'concrete', color: params.inlayColor, roughness: 0.8, doubleSided: true });
const band = api.lathe([[R + 0.18, wallH - 0.1], [R + 0.18, wallH + 0.1], [R - 0.18, wallH + 0.1], [R - 0.18, wallH - 0.1], [R + 0.18, wallH - 0.1]], 72);
api.add(band, { preset: 'metal', color: params.accentColor, roughness: 0.5, metalness: 0.4, doubleSided: true });
const rise = apex - wallH;
const prof = [];
for (let t = 0; t <= 90.001; t += 7.5) {
  const tr = t * Math.PI / 180;
  prof.push([Math.max(0.001, (R + 0.02) * Math.cos(tr)), wallH + rise * Math.sin(tr)]);
}
const shell = api.lathe(prof, 72);
if (params.glass) {
  api.add(shell, { preset: 'glass', color: params.glassColor, opacity: 0.28, roughness: 0.05, doubleSided: true });
} else {
  api.add(shell, { preset: 'plastic', color: params.panelColor, roughness: 0.6, doubleSided: true });
}
let ribs = null;
for (let k = 0; k < 12; k++) {
  const phi = k * Math.PI / 6;
  const path = [];
  for (let t = 0; t <= 90.001; t += 10) {
    const tr = t * Math.PI / 180;
    const rho = (R + 0.04) * Math.cos(tr);
    path.push([rho * Math.cos(phi), wallH + rise * Math.sin(tr) + 0.02, rho * Math.sin(phi)]);
  }
  const tb = api.tube(path, 0.06, 6);
  if (ribs) ribs.merge(tb); else ribs = tb;
}
for (const f of [0.35, 0.7]) {
  const tr = Math.asin(f);
  const ring = api.torus((R + 0.04) * Math.cos(tr), 0.05).rotate(90, 0, 0).translate(0, wallH + rise * f + 0.02, 0);
  ribs.merge(ring);
}
api.add(ribs, { preset: 'metal', color: params.accentColor, roughness: 0.5, metalness: 0.5, doubleSided: true });
api.collider({ kind: 'cylinder', halfHeight: floorH / 2, radius: R, offset: [0, floorH / 2, 0] });
for (const c of colliders) api.collider(c);
return api.build();
